                c.commit();
                return result;
            } catch (Throwable t) {
                c.rollback();
                throw t;
            }
        }
    }

    @Override
    public void close() {
        ds.close();
    }

    private static final String SCHEMA = """
            CREATE TABLE IF NOT EXISTS rooms (
